<section class="page-hero"><div class="container"><h1><?= e(__('pages.contact')) ?></h1><p class="lead"><?= e(__('pages.contact_lead')) ?></p></div></section>
<section class="section"><div class="container split">
    <form class="panel stack" method="post" action="<?= e(url('/contact')) ?>"><?= csrf_field() ?><label><?= e(__('fields.name')) ?><input name="name" value="<?= e((string) old('name')) ?>" required></label><label><?= e(__('fields.email')) ?><input type="email" name="email" value="<?= e((string) old('email')) ?>" required></label><label><?= e(__('fields.phone')) ?><input name="phone" value="<?= e((string) old('phone')) ?>"></label><label><?= e(__('fields.subject')) ?><input name="subject" value="<?= e((string) old('subject')) ?>"></label><label><?= e(__('fields.message')) ?><textarea name="message" rows="5" required><?= e((string) old('message')) ?></textarea></label><?php if (error('message')): ?><p class="form-error"><?= e(error('message')) ?></p><?php endif; ?><button class="btn btn-primary" type="submit"><?= e(__('contact.send')) ?></button></form>
    <aside class="panel"><h2><?= e(setting('company_name', 'AtteCert')) ?></h2><ul class="contact-list"><li><?= icon('pin', 'icon icon-sm') ?> <?= e(setting('address')) ?></li><li><?= icon('phone', 'icon icon-sm') ?> <?= e(setting('phone')) ?></li><li><?= icon('mail', 'icon icon-sm') ?> <?= e(setting('email')) ?></li><li><?= icon('clock', 'icon icon-sm') ?> <?= e(setting('hours')) ?></li></ul><?php if (setting('map_url')): ?><p><a href="<?= e(setting('map_url')) ?>" rel="noopener noreferrer"><?= e(__('contact.map')) ?></a></p><?php endif; ?></aside>
</div></section>
